export async function createSecretStore(
  options: SecretStoreOptions,
): Promise<SecretStore> {
  const { storage, masterPassword } = options;

  const SALT_KEY = "__secret_store_salt__";
  const encoder = new TextEncoder();
  const decoder = new TextDecoder();

  // Get or create salt
  let salt: Uint8Array;
  const storedSalt = await storage.get(SALT_KEY);
  if (storedSalt !== undefined) {
    salt = base64ToBytes(storedSalt);
  } else {
    salt = crypto.getRandomValues(new Uint8Array(16));
    await storage.set(SALT_KEY, bytesToBase64(salt));
  }

  // Derive AES-256-GCM key from master password
  const passwordBuf = encoder.encode(masterPassword);
  const pbkdf2Key = await crypto.subtle.importKey(
    "raw",
    passwordBuf,
    { name: "PBKDF2" },
    false,
    ["deriveKey"],
  );

  const aesKey = await crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt,
      iterations: 100000,
      hash: "SHA-256",
    },
    pbkdf2Key,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );

  function makeStorageKey(owner: string, name: string): string {
    const ownerB64 = bytesToBase64(encoder.encode(owner));
    const nameB64 = bytesToBase64(encoder.encode(name));
    return `secret:${ownerB64}:${nameB64}`;
  }

  return {
    async put(owner: string, name: string, value: string): Promise<void> {
      const iv = crypto.getRandomValues(new Uint8Array(12));
      const valueBuf = encoder.encode(value);

      const ciphertext = await crypto.subtle.encrypt(
        { name: "AES-GCM", iv },
        aesKey,
        valueBuf,
      );

      // Prepend IV to ciphertext (which includes GCM tag)
      const combined = new Uint8Array(12 + ciphertext.byteLength);
      combined.set(iv, 0);
      combined.set(new Uint8Array(ciphertext), 12);

      await storage.set(makeStorageKey(owner, name), bytesToBase64(combined));
    },

    async get(owner: string, name: string): Promise<string | undefined> {
      const storageKey = makeStorageKey(owner, name);
      const stored = await storage.get(storageKey);
      if (stored === undefined) return undefined;

      let combined: Uint8Array;
      try {
        combined = base64ToBytes(stored);
      } catch {
        throw new Error("Corrupted secret data: invalid encoding");
      }

      if (combined.length < 12) {
        throw new Error("Corrupted secret data: too short");
      }

      const iv = combined.slice(0, 12);
      const ciphertext = combined.slice(12);

      try {
        const plaintext = await crypto.subtle.decrypt(
          { name: "AES-GCM", iv },
          aesKey,
          ciphertext,
        );
        return decoder.decode(plaintext);
      } catch {
        throw new Error("Decryption failed: secret has been tampered with");
      }
    },

    async list(owner: string): Promise<string[]> {
      const allKeys = await storage.keys();
      const ownerB64 = bytesToBase64(encoder.encode(owner));
      const prefix = `secret:${ownerB64}:`;

      const names: string[] = [];
      for (const k of allKeys) {
        if (k.startsWith(prefix)) {
          const nameB64 = k.slice(prefix.length);
          try {
            const nameBytes = base64ToBytes(nameB64);
            names.push(decoder.decode(nameBytes));
          } catch {
            // Skip malformed entries
          }
        }
      }
      names.sort();
      return names;
    },

    async remove(owner: string, name: string): Promise<boolean> {
      const storageKey = makeStorageKey(owner, name);
      const exists = await storage.get(storageKey);
      if (exists === undefined) return false;
      await storage.delete(storageKey);
      return true;
    },
  };
}

function bytesToBase64(bytes: Uint8Array): string {
  let binary = "";
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function base64ToBytes(b64: string): Uint8Array {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}
